  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  // sky
  brush.fillBleed(1);
  brush.circle(0, 0, 300);
  brush.fillBleed(0.5);
  brush.beginShape();
  brush.vertex(300, 300);
  brush.vertex(400, 0);
  brush.vertex(300, -300);
  brush.endShape(true);
  // hills
  brush.fill("#b2cd93");
  brush.beginShape();
  brush.vertex(200, 200);
  brush.vertex(250, 250);
  brush.vertex(200, 300);
  brush.endShape(true);
  // sun
  brush.fill("#ec4892");
  brush.beginShape();
  brush.vertex(200, 100);
  brush.vertex(240, 200);
  brush.vertex(260, 150);
  brush.endShape(true);
}

